class Solution:
    def addTwoNumbers(self, l1, l2):
        dummy = cur = ListNode(); carry = 0
        while l1 or l2 or carry:
            s = (l1.val if l1 else 0) + (l2.val if l2 else 0) + carry
            carry, d = divmod(s, 10)
            cur.next = ListNode(d); cur = cur.next
            l1 = l1.next if l1 else None; l2 = l2.next if l2 else None
        return dummy.next

class Solution:
    def addTwoNumbers(self, l1, l2):
        def toint(n):
            v, mul = 0, 1
            while n: v += n.val * mul; mul *= 10; n = n.next
            return v
        total = toint(l1) + toint(l2)
        if total == 0: return ListNode(0)
        dummy = cur = ListNode()
        while total:
            cur.next = ListNode(total % 10); cur = cur.next; total //= 10
        return dummy.next

