class Solution:
    def longestPalindrome(self, s):
        n = len(s); dp = [[False] * n for _ in range(n)]; start, best = 0, 1
        for i in range(n): dp[i][i] = True
        for length in range(2, n + 1):
            for i in range(n - length + 1):
