class Solution:
    def generateParenthesis(self, n):
        def valid(s):
            bal = 0
            for ch in s:
                bal += 1 if ch == '(' else -1
                if bal < 0: return False
            return bal == 0
        return [''.join(p) for p in product('()', repeat=2 * n) if valid(p)]

class Solution:
    def generateParenthesis(self, n):
        if n == 0: return ['']
        res = []
        for i in range(n):
            for left in self.generateParenthesis(i):
                for right in self.generateParenthesis(n - 1 - i): res.append('(' + left + ')' + right)
        return res

