class Solution:
    def findSubstring(self, s, words):
        w, n = len(words[0]), len(words); need = Counter(words); res = []
        for off in range(w):
            l = off; seen = Counter(); count = 0
            for r in range(off, len(s) - w + 1, w):
                word = s[r:r + w]
                if word in need:
                    seen[word] += 1; count += 1
                    while seen[word] > need[word]:
                        seen[s[l:l + w]] -= 1; l += w; count -= 1
