class ZigzagIterator:
    def __init__(self, v1, v2):
        self.vs = [v1, v2]
        self.pos = [0, 0]
        self.turn = 0
    def _skip(self):
        for _ in range(2):
            if self.pos[self.turn] < len(self.vs[self.turn]): return
            self.turn ^= 1
    def next(self):
