class Solution:
    def boundaryOfBinaryTree(self, root):
        if not root: return []
        def is_leaf(n): return not n.left and not n.right
        res = [root.val] if not is_leaf(root) else []
        node = root.left
        while node:
            if not is_leaf(node): res.append(node.val)
            node = node.left if node.left else node.right
        def leaves(n):
            if not n: return
            if is_leaf(n): res.append(n.val)
            leaves(n.left)
            leaves(n.right)
        leaves(root)
        right = []
