        if not root.left and not root.right: return [root.val]
        left, leaves, right = [], [], []
        def dfs(node, on_left, on_right):
            if not node: return
            if not node.left and not node.right:
                leaves.append(node.val)
                return
            if on_left: left.append(node.val)
            if on_right: right.append(node.val)
            dfs(node.left, on_left, on_right and not node.right)
            dfs(node.right, on_left and not node.left, on_right)
