class Solution:
    def criticalConnections(self, n, connections):
        g = defaultdict(list)
        for u, v in connections:
            g[u].append(v)
            g[v].append(u)
        disc, low, out, timer = {}, {}, [], [0]
        def dfs(u, parent):
            disc[u] = low[u] = timer[0]
            timer[0] += 1
            for v in g[u]:
                if v == parent: continue
                if v not in disc:
                    dfs(v, u)
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]: out.append([u, v])
                else:
                    low[u] = min(low[u], disc[v])
        dfs(0, -1)
        return out

