            g = defaultdict(list)
            for i, (u, v) in enumerate(connections):
                if i != skip:
                    g[u].append(v)
                    g[v].append(u)
            seen, st = {0}, [0]
            while st:
                x = st.pop()
                for y in g[x]:
                    if y not in seen:
                        seen.add(y)
                        st.append(y)
            return len(seen) == n
        return [list(connections[i]) for i in range(len(connections)) if not connected(i)]

