class FizzBuzz:
    def __init__(self, n):
        self.n = n
        self.i = 1
        self.cv = threading.Condition()
    def _run(self, matches, action):
        while True:
            with self.cv:
                while self.i <= self.n and not matches(self.i):
                    self.cv.wait()
                if self.i > self.n:
                    self.cv.notify_all()
                    return
                action(self.i)
                self.i += 1
                self.cv.notify_all()
    def fizz(self, printFizz):
        self._run(lambda i: i % 3 == 0 and i % 5 != 0, lambda i: printFizz())
    def buzz(self, printBuzz):
