import threading

class FizzBuzz:
    def __init__(self, n):
        self.n = n
        self.i = 1
        self.sem = {k: threading.Semaphore(0) for k in ('fizz', 'buzz', 'fizzbuzz')}
        self.num = threading.Semaphore(1)
        self.done = threading.Event()
    def _kind(self, i):
        return 'fizzbuzz' if i % 15 == 0 else 'fizz' if i % 3 == 0 else 'buzz' if i % 5 == 0 else 'num'
    def _advance(self):
        self.i += 1
        if self.i > self.n:
            self.done.set()
            for s in self.sem.values(): s.release()
            self.num.release()
            return
        k = self._kind(self.i)
        (self.num if k == 'num' else self.sem[k]).release()
    def fizz(self, printFizz):
        while True:
            self.sem['fizz'].acquire()
            if self.done.is_set(): return
            printFizz()
            self._advance()
    def buzz(self, printBuzz):
        while True:
            self.sem['buzz'].acquire()
            if self.done.is_set(): return
            printBuzz()
            self._advance()
    def fizzbuzz(self, printFizzBuzz):
        while True:
            self.sem['fizzbuzz'].acquire()
            if self.done.is_set(): return
            printFizzBuzz()
            self._advance()
    def number(self, printNumber):
        while True:
            self.num.acquire()
            if self.done.is_set(): return
            printNumber(self.i)
            self._advance()

