class Solution:
    def minNumberOfSemesters(self, n, relations, k):
        pre = [0] * n
        for a, b in relations: pre[b - 1] |= 1 << (a - 1)
        full = (1 << n) - 1
        dp = [n + 1] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] > n: continue
            avail = 0
            for i in range(n):
                if not mask >> i & 1 and pre[i] & mask == pre[i]: avail |= 1 << i
            sub = avail
            while sub:
                if bin(sub).count('1') <= k:
                    nm = mask | sub
                    if dp[mask] + 1 < dp[nm]: dp[nm] = dp[mask] + 1
                sub = (sub - 1) & avail
        return dp[full]

class Solution:
    def minNumberOfSemesters(self, n, relations, k):
        pre = [0] * n
        for a, b in relations: pre[b - 1] |= 1 << (a - 1)
        full = (1 << n) - 1
        level, seen, sem = {0}, {0}, 0
        while level:
            if full in level: return sem
            nxt = set()
            for mask in level:
                avail = [i for i in range(n) if not mask >> i & 1 and pre[i] & mask == pre[i]]
                for r in range(min(k, len(avail)), 0, -1):
                    for comb in combinations(avail, r):
                        nm = mask
                        for i in comb: nm |= 1 << i
                        if nm not in seen:
                            seen.add(nm)
                            nxt.add(nm)
            level = nxt
            sem += 1
        return -1

