class Solution:
    def getLengthOfOptimalCompression(self, s, k):
        n = len(s)
        @lru_cache(None)
        def go(i, left):
            if left < 0: return float('inf')
            if i >= n - left: return 0
            best = go(i + 1, left - 1)
            same = diff = 0
            for j in range(i, n):
                if s[j] == s[i]: same += 1
                else: diff += 1
                if diff > left: break
                length = 1 if same == 1 else 1 + len(str(same))
                best = min(best, length + go(j + 1, left - diff))
