        return ans if ans < INF else -1

class Solution:
    def minCost(self, maxTime, edges, passingFees):
        n = len(passingFees)
        g = defaultdict(list)
        for u, v, w in edges:
            g[u].append((v, w))
            g[v].append((u, w))
        best = {}
        pq = [(passingFees[0], 0, 0)]
        while pq:
            cost, t, u = heappop(pq)
            if u == n - 1: return cost
            if u in best and best[u] <= t: continue
            best[u] = t
            for v, w in g[u]:
