class Solution:
    def getDirections(self, root, startValue, destValue):
        def path(node, target, acc):
            if node.val == target: return True
            if node.left and path(node.left, target, acc):
                acc.append('L')
                return True
            if node.right and path(node.right, target, acc):
                acc.append('R')
                return True
            return False
        a, b = [], []
        path(root, startValue, a)
        path(root, destValue, b)
        a.reverse()
        b.reverse()
        i = 0
        while i < len(a) and i < len(b) and a[i] == b[i]: i += 1
        return 'U' * (len(a) - i) + ''.join(b[i:])

class Solution:
    def getDirections(self, root, startValue, destValue):
        def lca(node):
            if not node or node.val in (startValue, destValue): return node
            l, r = lca(node.left), lca(node.right)
            return node if l and r else (l or r)
        def find(node, target, acc):
            if node.val == target: return True
            for ch, d in ((node.left, 'L'), (node.right, 'R')):
                if ch:
                    acc.append(d)
                    if find(ch, target, acc): return True
                    acc.pop()
            return False
        top = lca(root)
        a, b = [], []
        find(top, startValue, a)
        find(top, destValue, b)
        return 'U' * len(a) + ''.join(b)

