            nonlocal best
            if not node: return 0
            l, r = go(node.left), go(node.right)
            if node.val == start:
                best = max(l, r)
                return -1
            if l >= 0 and r >= 0: return 1 + max(l, r)
            d = abs(l) if l < 0 else abs(r)
