class Solution:
    def mostBooked(self, n, meetings):
        meetings.sort()
        free = list(range(n))
        heapify(free)
        busy = []
        count = [0] * n
        for start, end in meetings:
            while busy and busy[0][0] <= start:
                _, room = heappop(busy)
                heappush(free, room)
            if free:
                room = heappop(free)
                heappush(busy, (end, room))
