        meetings.sort()
        free_at = [0] * n
        count = [0] * n
        for start, end in meetings:
            dur = end - start
            for r in range(n):
                if free_at[r] <= start:
                    free_at[r] = end
                    count[r] += 1
                    break
            else:
                r = min(range(n), key=lambda x: (free_at[x], x))
                free_at[r] += dur
                count[r] += 1
        return count.index(max(count))

