class SQL:
    def __init__(self, names, columns):
        self.t = {n: {'cols': c, 'rows': [], 'removed': set()} for n, c in zip(names, columns)}
    def ins(self, name, row):
        t = self.t.get(name)
        if t is None or len(row) != t['cols']: return False
        t['rows'].append(row)
        return True
    def rmv(self, name, rowId):
        t = self.t.get(name)
        if t is not None and 1 <= rowId <= len(t['rows']): t['removed'].add(rowId)
    def sel(self, name, rowId, columnId):
        t = self.t.get(name)
        if t is None or not 1 <= rowId <= len(t['rows']) or rowId in t['removed'] or not 1 <= columnId <= t['cols']: return '<null>'
        return t['rows'][rowId - 1][columnId - 1]
    def exp(self, name):
        t = self.t.get(name)
        if t is None: return []
        return [str(i + 1) + ',' + ','.join(r) for i, r in enumerate(t['rows']) if i + 1 not in t['removed']]

