class Solution:
    def totalCost(self, costs, k, candidates):
        n = len(costs)
        left = costs[:candidates]; heapify(left)
        right = costs[max(candidates, n - candidates):]; heapify(right)
        i, j, total = candidates, n - candidates - 1, 0
        for _ in range(k):
            if not right or (left and left[0] <= right[0]):
                total += heappop(left)
                if i <= j: heappush(left, costs[i]); i += 1
            else:
                total += heappop(right)
                if i <= j: heappush(right, costs[j]); j -= 1
        return total

class Solution:
    def totalCost(self, costs, k, candidates):
        costs = list(costs); total = 0
        for _ in range(k):
            n = len(costs)
            window = list(range(min(candidates, n))) + list(range(max(candidates, n - candidates), n))
            i = min(window, key=lambda i: (costs[i], i))
            total += costs[i]; costs.pop(i)
        return total

