class Solution:
    def mostProfitablePath(self, edges, bob, amount):
        n = len(amount)
        g = defaultdict(list)
        for a, b in edges:
            g[a].append(b)
            g[b].append(a)
        bob_time = {}
        def find(u, p, d):
            if u == 0:
                bob_time[u] = d
                return True
            for v in g[u]:
                if v != p and find(v, u, d + 1):
                    bob_time[u] = d
                    return True
            return False
        find(bob, -1, 0)
        best = float('-inf')
        def go(u, p, t, gain):
            nonlocal best
            bt = bob_time.get(u, float('inf'))
            if t < bt: gain += amount[u]
            elif t == bt: gain += amount[u] // 2
            kids = [v for v in g[u] if v != p]
            if not kids: best = max(best, gain)
            for v in kids: go(v, u, t + 1, gain)
        go(0, -1, 0, 0)
        return best

class Solution:
    def mostProfitablePath(self, edges, bob, amount):
        n = len(amount)
        g = defaultdict(list)
        for a, b in edges:
            g[a].append(b)
            g[b].append(a)
        parent = [-1] * n
        q = deque([0])
        seen = {0}
        while q:
            u = q.popleft()
            for v in g[u]:
                if v not in seen:
                    seen.add(v)
                    parent[v] = u
                    q.append(v)
        bob_time = [float('inf')] * n
        u, t = bob, 0
        while u != -1:
            bob_time[u] = t
            u, t = parent[u], t + 1
        best = float('-inf')
        stack = [(0, -1, 0, 0)]
        while stack:
            u, p, t, gain = stack.pop()
            if t < bob_time[u]: gain += amount[u]
            elif t == bob_time[u]: gain += amount[u] // 2
            kids = [v for v in g[u] if v != p]
            if not kids: best = max(best, gain)
            for v in kids: stack.append((v, u, t + 1, gain))
        return best

