class Allocator:
    def __init__(self, n):
        self.n = n
        self.blocks = []
    def allocate(self, size, mID):
        prev_end = 0
        for idx, (s, sz, m) in enumerate(self.blocks):
            if s - prev_end >= size:
                self.blocks.insert(idx, (prev_end, size, mID))
                return prev_end
            prev_end = s + sz
        if self.n - prev_end >= size:
            self.blocks.append((prev_end, size, mID))
            return prev_end
        return -1
    def freeMemory(self, mID):
        freed = sum(sz for s, sz, m in self.blocks if m == mID)
        self.blocks = [b for b in self.blocks if b[2] != mID]
        return freed

