class Solution:
    def countGoodSubsequences(self, s):
        MOD = 10 ** 9 + 7
        cnt = Counter(s)
        mx = max(cnt.values())
        total = 0
        for f in range(1, mx + 1):
            ways = 1
            for c in cnt.values():
