    def countGoodSubsequences(self, s):
        MOD = 10 ** 9 + 7
        n, total = len(s), 0
        for mask in range(1, 1 << n):
            cnt = Counter(s[i] for i in range(n) if mask >> i & 1)
            if len(set(cnt.values())) == 1: total += 1
        return total % MOD

