class Solution:
    def minimumTime(self, grid):
        m, n = len(grid), len(grid[0])
        if grid[0][1] > 1 and grid[1][0] > 1: return -1
        dist = [[float('inf')] * n for _ in range(m)]
        dist[0][0] = 0
        pq = [(0, 0, 0)]
        while pq:
            t, r, c = heappop(pq)
            if (r, c) == (m - 1, n - 1): return t
            if t > dist[r][c]: continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = r + dr, c + dc
                if 0 <= a < m and 0 <= b < n:
                    nt = max(t + 1, grid[a][b])
                    if (nt - (t + 1)) % 2: nt += 1
                    if nt < dist[a][b]:
                        dist[a][b] = nt
                        heappush(pq, (nt, a, b))
        return -1

class Solution:
    def minimumTime(self, grid):
        m, n = len(grid), len(grid[0])
        if grid[0][1] > 1 and grid[1][0] > 1: return -1
        INF = float('inf')
        dist = [[INF] * n for _ in range(m)]
        dist[0][0] = 0
        changed = True
        while changed:
            changed = False
            for r in range(m):
                for c in range(n):
                    t = dist[r][c]
                    if t == INF: continue
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        a, b = r + dr, c + dc
                        if 0 <= a < m and 0 <= b < n:
