class Solution:
    def minimumTime(self, hens, grains):
        hens, grains = sorted(hens), sorted(grains)
        def ok(t):
            j = 0
            for h in hens:
                if j == len(grains): return True
                if grains[j] < h:
                    d = h - grains[j]
                    if d > t: return False
                    reach = h + max(t - 2 * d, (t - d) // 2)
                else:
                    reach = h + t
                while j < len(grains) and grains[j] <= reach: j += 1
            return j == len(grains)
        lo, hi = 0, 2 * (max(hens + grains) - min(hens + grains))
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid): hi = mid
            else: lo = mid + 1
        return lo

class Solution:
