                if j == len(grains): return True
                if grains[j] < h:
                    d = h - grains[j]
                    if d > t: return False
                    reach = h + max(t - 2 * d, (t - d) // 2)
                else:
                    reach = h + t
                while j < len(grains) and grains[j] <= reach: j += 1
            return j == len(grains)
        t = 0
        while not ok(t): t += 1
        return t

