        tree = [0] * (4 * size)
        def update(node, lo, hi, pos, val):
            if lo == hi:
                tree[node] = val
                return
            mid = (lo + hi) // 2
            if pos <= mid: update(2 * node, lo, mid, pos, val)
            else: update(2 * node + 1, mid + 1, hi, pos, val)
            tree[node] = max(tree[2 * node], tree[2 * node + 1])
        def query(node, lo, hi, l, r):
            if r < lo or hi < l or l > r: return 0
            if l <= lo and hi <= r: return tree[node]
            mid = (lo + hi) // 2
            return max(query(2 * node, lo, mid, l, r), query(2 * node + 1, mid + 1, hi, l, r))
        obs = [0]
        ans = []
        for q in queries:
            if q[0] == 1:
                x = q[1]
                i = bisect_left(obs, x)
                prev = obs[i - 1]
                update(1, 0, size - 1, x, x - prev)
                if i < len(obs): update(1, 0, size - 1, obs[i], obs[i] - x)
                obs.insert(i, x)
