class Solution:
    def numberOfAlternatingGroups(self, colors, k):
        n = len(colors)
        ext = colors + colors[:k - 1]
        count = 0
        run = 1
        for i in range(1, len(ext)):
            run = run + 1 if ext[i] != ext[i - 1] else 1
            if run >= k: count += 1
        return count

class Solution:
    def numberOfAlternatingGroups(self, colors, k):
        n = len(colors)
        count = 0
        for s in range(n):
            if all(colors[(s + i) % n] != colors[(s + i + 1) % n] for i in range(k - 1)): count += 1
        return count

