class Solution:
    def perfectPairs(self, nums):
        a = sorted(abs(x) for x in nums)
        count, j = 0, 0
        for i in range(len(a)):
            while a[j] * 2 < a[i]: j += 1
            count += i - j
        return count

class Solution:
    def perfectPairs(self, nums):
        count = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                a, b = nums[i], nums[j]
                d1, d2 = abs(a - b), abs(a + b)
                if min(d1, d2) <= min(abs(a), abs(b)) and max(d1, d2) >= max(abs(a), abs(b)): count += 1
        return count

