class Solution:
    def minAbsoluteDifference(self, nums):
        last1 = last2 = None
        best = float('inf')
        for i, x in enumerate(nums):
            if x == 1:
                last1 = i
                if last2 is not None: best = min(best, i - last2)
            elif x == 2:
                last2 = i
                if last1 is not None: best = min(best, i - last1)
        return best if best != float('inf') else -1

class Solution:
    def minAbsoluteDifference(self, nums):
        best = float('inf')
        for i, x in enumerate(nums):
            if x != 1: continue
            for j, y in enumerate(nums):
                if y == 2: best = min(best, abs(i - j))
        return best if best != float('inf') else -1

